const body = $input.first().json.body || $input.first().json;

const inboxContent = body.inbox || body.text || '';
const date = body.date || new Date().toISOString().split('T')[0];

return [{
  json: {
    inboxContent,
    date,
    length: inboxContent.length
  }
}];

const input = $('Parse Inbox').first().json;
const raw = $input.first().json.content?.[0]?.text || $input.first().json.message?.content || $input.first().json.output || '';

const synthesisMd = `---
type: daily-synthesis
date: ${input.date}
generated: ${new Date().toISOString()}
---

# Síntesis Diaria — ${input.date}

${raw}

---

## 📎 Backlinks
- [[Daily-Inbox]]
- [[PROJECTS/ZENTI]]
- [[PROJECTS/Charly.io]]

#síntesis-diaria
`;

const filename = `${input.date}-sintesis.md`;
const filepath = `SYNTHESIS/${filename}`;

return [{
  json: {
    status: 'ok',
    date: input.date,
    filename,
    filepath,
    synthesisMd
  }
}];
